SELECT sku, product_name, pack_size, flow_type
FROM store.products
WHERE lower(product_name) LIKE '%atta%' AND pack_size = '5 kg';

SELECT sku, name, pack, flow
FROM store.products
WHERE lower(name) LIKE '%atta%' AND pack = '5 kg';

SELECT date, units_sold, revenue_inr
FROM store.daily_sales
WHERE sku = 'ATTA-WW-5KG' AND date >= DATE '2026-06-01' AND date <= DATE '2026-06-30';

